import { InasistenciaRecord } from '../types';

function cleanDoc(str: string): string {
  return str ? str.replace(/\D/g, '') : '';
}

function extractCod(str: string): string {
  const match = str.match(/\d{6,8}/);
  return match ? match[0] : str.trim();
}

