export const INITIAL_INASISTENCIAS_RECORDS: InasistenciaRecord[] = RAW_ROWS.map((r, idx) => {
  const codFicha = extractCod(r[0]);
  const docNum = cleanDoc(r[2]);
  return {
    id: `inasist-init-${idx + 1}`,
    ficha: r[0],
    codigoFicha: codFicha,
    programa: r[0],
    instructor: r[1],
    idAprendiz: r[2],
    docNumerico: docNum,
    aprendiz: r[3],
    fechaInicio: r[4],
    fechaFin: r[5],
    cantHoras: Number(r[6]) || 0,
    justificacion: r[7] || "SIN JUSTIFICACION",
    observaciones: r[8] || ""
  };
});
